import { Effect } from "effect"

export const preview = Effect.gen(function*() {
  return new AbortController().signal
})

/// <reference lib="esnext.disposable" />
import { Effect } from "effect"

declare const acquire: Effect.Effect<AsyncDisposable>

export const resource = Effect.acquireRelease(
  acquire,
  (resource) => Effect.promise(() => resource[Symbol.asyncDispose]())
)

import { Effect } from "effect"

declare const values: ReadonlyArray<number>

export const program = Effect.all(
  values.map((value) => Effect.succeed(value + 1))
)

import { Effect } from "effect"

export const preview = Effect.gen(function*() {
  yield* Effect.context<unknown>()
  return yield* Effect.fail<any>("boom")
})

export const preview = async () => {
