}

import { Data, Effect } from "effect"

class NotFound extends Data.TaggedError("NotFound")<{}> {}
class Timeout extends Data.TaggedError("Timeout")<{}> {}
class Unauthorized extends Data.TaggedError("Unauthorized")<{}> {}

declare const program: Effect.Effect<string, NotFound | Timeout | Unauthorized>

export const recovered = program.pipe(
  Effect.catch((error) => {
    switch (error._tag) {
      case "NotFound":
        return Effect.succeed("guest")
      case "Timeout":
        return Effect.succeed("retrying")
      default:
        return Effect.fail(error)
    }
  })
)

import { Effect } from "effect"

class WrappedError {
  constructor(readonly cause: unknown) {}
}

export const preview = Effect.fail("boom").pipe(
  Effect.catch((cause) => Effect.fail(new WrappedError(cause)))
)

import { Data, Effect } from "effect"

class NotFound extends Data.TaggedError("NotFound")<{}> {}
class DatabaseError extends Data.TaggedError("DatabaseError")<{}> {}

declare const program: Effect.Effect<string, NotFound | DatabaseError>

export const recovered = program.pipe(
  Effect.catch((error) =>
    error instanceof NotFound ? Effect.succeed("guest") : Effect.fail(error)
  )
)

import { Effect } from "effect"

declare const readConfig: Effect.Effect<string, Error>

export const program = readConfig.pipe(
  Effect.catch((error) => Effect.die(error))
)

import { Data, Effect } from "effect"

class NotFound extends Data.TaggedError("NotFound")<{}> {}
class Timeout extends Data.TaggedError("Timeout")<{}> {}

declare const program: Effect.Effect<string, NotFound | Timeout>

export const recovered = program.pipe(
  Effect.catchIf(
    (error) => error._tag === "NotFound",
    () => Effect.succeed("guest")
  )
)

import { Effect } from "effect"

declare const save: Effect.Effect<void, Error>
declare const rollback: Effect.Effect<void>

export const program = save.pipe(
  Effect.catch(error => rollback.pipe(Effect.andThen(Effect.fail(error))))
)

import { Effect } from "effect"

class RetryReason {
  readonly _tag = "RetryReason"
}

class FatalReason {
  readonly _tag = "FatalReason"
}

class AppError {
  readonly _tag = "AppError"
  constructor(readonly reason: RetryReason | FatalReason) {}
}

declare const program: Effect.Effect<string, AppError>

export const fixable = program.pipe(
  Effect.catchTag("AppError", (error) => {
    if (error.reason._tag === "RetryReason") return Effect.succeed("retry")
    return Effect.fail(error)
  })
)

